      "content": "import { expect, mock, test } from 'bun:test';
import { DomainError, type DomainEvent, type UseCaseContext } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { CreateTask, createTaskOutput } from '../application/create-task';
import { Task } from '../domain/task';
import { TaskCreated } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

function fixture() {
  const repository = new InMemoryTaskRepository();
  const findById = mock(async (id: string) => repository.findById(id));
  const save = mock(async (task: Task) => repository.save(task));
  const publish = mock(async (_events: readonly DomainEvent[]) => {});
  const ctx: UseCaseContext = { correlationId: 'creation-1', causationId: 'creation-1', publish };
  const useCase = new CreateTask({ findById, save });
  return { repository, findById, save, publish, ctx, useCase };
}

test(covers([
  'usecase:create_task',
  'criterion:0001/persistencia-criacao',
], 'cria e salva t1 antes de publicar TaskCreated, retorna pending e rejeita o mesmo id'), async () => {
  const { repository, findById, save, publish, ctx, useCase } = fixture();
  const operations: string[] = [];
  expect(await repository.findById('t1')).toBeNull();
  save.mockImplementation(async (task: Task) => {
    expect(task.status).toBe('pending');
    await repository.save(task);
    operations.push('saved');
  });
  publish.mockImplementation(async (events: readonly DomainEvent[]) => {
    expect(operations).toEqual(['saved']);
    const stored = await repository.findById('t1');
    expect(stored?.title).toBe('Fazer  tarefa');
    expect(stored?.status).toBe('pending');
    expect(events).toHaveLength(1);
    expect(events[0]).toBeInstanceOf(TaskCreated);
    expect(events[0]!.payload).toEqual({ taskId: 't1', title: 'Fazer  tarefa' });
    operations.push('published');
  });

  const output = await useCase.execute({ task_id: 't1', title: ' \tFazer  tarefa\n ' }, ctx);

  expect(output).toEqual({ task_id: 't1', title: 'Fazer  tarefa', status: 'pending' });
  expect(createTaskOutput.parse(output)).toEqual(output);
  const stored = await repository.findById('t1');
  expect(stored).toBeInstanceOf(Task);
  expect(save).toHaveBeenCalledWith(stored);
  expect(stored?.pullEvents()).toEqual([]);
  const failure = await useCase.execute({ task_id: 't1', title: 'Outro título' }, ctx).catch(error => error);

  expect(failure).toBeInstanceOf(DomainError);
  expect(failure).toHaveProperty('code', 'TASK_ALREADY_EXISTS');
  expect(findById).toHaveBeenCalledTimes(2);
  expect(findById).toHaveBeenNthCalledWith(1, 't1');
  expect(findById).toHaveBeenNthCalledWith(2, 't1');
  expect(save).toHaveBeenCalledTimes(1);
  expect(publish).toHaveBeenCalledTimes(1);
  expect(operations).toEqual(['saved', 'published']);
  expect(await repository.findById('t1')).toBe(stored);
  expect(stored?.title).toBe('Fazer  tarefa');
  expect(stored?.status).toBe('pending');
  expect(stored?.pullEvents()).toEqual([]);
});

test(covers(['usecase:create_task'], 'rejeita título vazio após normalização sem salvar nem publicar'), async () => {
  const { repository, save, publish, ctx, useCase } = fixture();
  const failure = await useCase.execute({ task_id: 't1', title: ' \t\n ' }, ctx).catch(error => error);

  expect(failure).toBeInstanceOf(DomainError);
  expect(failure).toHaveProperty('code', 'TASK_TITLE_REQUIRED');
  expect(save).not.toHaveBeenCalled();
  expect(publish).not.toHaveBeenCalled();
  expect(await repository.findById('t1')).toBeNull();
});

test(covers(['usecase:create_task'], 'propaga falha de consulta sem salvar nem publicar'), async () => {
  const { findById, save, publish, ctx, useCase } = fixture();
  const failure = new Error('Falha ao consultar');
  findById.mockImplementation(async () => { throw failure; });

